// Mirrors hub/sidebars.js exactly. `companies` and `deals` (fetched from
// Firestore server-side and passed down) fill the auto-generated New Deals /
// Watchlist / Pipeline / Qualified Deals / Deal Summaries subcategories the
// way Docusaurus's `{ type: 'autogenerated', dirName: ... }` used to -- each
// company's `stage` field decides which one of the four it lands in.
//
// The five deal-list categories below are marked `flat: true`: they still
// carry their full `items` list (needed so breadcrumbs/prev-next still
// resolve correctly on a company's detail page, and so the sidebar rail
// still highlights while browsing one), but DocsShell renders them as a
// single non-expanding link straight to the tab's page instead of a
// chevron-toggled dropdown -- those lists grow with every company added and
// would otherwise dump a long, ever-changing name list into the sidebar.
// Research/Projects keep the expand behavior since their item counts are
// small and fixed.
export function getSidebarTree(companies = [], deals = []) {
  return [
    { type: 'doc', href: '/docs/overview', label: 'Capabilities' },
    {
      type: 'category',
      label: 'Deal Summaries',
      flat: true,
      href: '/docs/deals',
      items: deals.map((d) => ({ type: 'doc', href: `/docs/deals/${d.id}`, label: d.companyName })),
    },
    {
      type: 'category',
      label: 'New Deals',
      flat: true,
      href: '/docs/new-deals',
      items: companies.filter((c) => c.stage === 'new').map((c) => ({ type: 'doc', href: `/docs/new-deals/${c.slug}`, label: c.name })),
    },
    {
      type: 'category',
      label: 'Watchlist',
      flat: true,
      href: '/docs/watchlist',
      items: companies.filter((c) => c.stage === 'watchlist').map((c) => ({ type: 'doc', href: `/docs/watchlist/${c.slug}`, label: c.name })),
    },
    {
      type: 'category',
      label: 'Pipeline',
      flat: true,
      href: '/docs/pipeline',
      items: companies.filter((c) => c.stage === 'pipeline').map((c) => ({ type: 'doc', href: `/docs/pipeline/${c.slug}`, label: c.name })),
    },
    {
      type: 'category',
      label: 'Qualified Deals',
      flat: true,
      href: '/docs/qualified-deals',
      items: companies.filter((c) => c.stage === 'qualified').map((c) => ({ type: 'doc', href: `/docs/qualified-deals/${c.slug}`, label: c.name })),
    },
    { type: 'doc', href: '/docs/hot-deals', label: 'Hot Deals', badge: 'NEW' },
    {
      type: 'category',
      label: 'VCs',
      collapsed: true,
      href: '/docs/vcs',
      items: [],
    },
    {
      type: 'category',
      label: 'Research',
      collapsed: true,
      href: '/docs/research',
      items: [
        { type: 'doc', href: '/docs/research/market-map', label: 'Market Map Directory' },
      ],
    },
    { type: 'doc', href: '/docs/research-chat', label: 'Research Chat' },
    {
      type: 'category',
      label: 'Projects',
      collapsed: true,
      items: [
        { type: 'doc', href: '/docs/projects/pitchbook-attio', label: 'PitchBook → Attio Pipeline' },
        { type: 'doc', href: '/docs/projects/apollo-reach-out', label: 'Apollo Reach Out' },
        { type: 'doc', href: '/docs/projects/intelligence', label: 'Deal Intelligence' },
        { type: 'doc', href: '/docs/projects/investment-memo', label: 'Investment Memo Generator' },
        { type: 'doc', href: '/docs/projects/hub-docs', label: 'Documentation System' },
      ],
    },
    { type: 'doc', href: '/docs/admin', label: 'Admin' },
  ];
}

// Walks the tree and returns the [{ label, href }] trail leading to `pathname`
// (excluding the tree root), the way Docusaurus's default breadcrumbs do.
export function getBreadcrumbs(pathname, tree) {
  function search(nodes, trail) {
    for (const node of nodes) {
      const nextTrail = [...trail, { label: node.label, href: node.href }];
      if (node.href === pathname) return nextTrail;
      if (node.items) {
        const found = search(node.items, nextTrail);
        if (found) return found;
      }
    }
    return null;
  }
  return search(tree, []) || [];
}

// True if `pathname` is this node or a descendant of it — used to
// auto-expand the "Companies" subcategory when viewing a company page.
export function containsPath(node, pathname) {
  if (node.href === pathname) return true;
  if (!node.items) return false;
  return node.items.some((child) => containsPath(child, pathname));
}

// Flattens the tree into the same linear doc order Docusaurus uses to
// generate its Previous/Next pagination — depth-first, including a
// category's own link (e.g. "Research") at the point it's encountered.
export function flattenDocs(tree) {
  const out = [];
  function walk(nodes) {
    for (const node of nodes) {
      if (node.href) out.push({ href: node.href, label: node.label });
      if (node.items) walk(node.items);
    }
  }
  walk(tree);
  return out;
}

export function getPrevNext(pathname, tree) {
  const flat = flattenDocs(tree);
  const i = flat.findIndex((d) => d.href === pathname);
  if (i === -1) return { prev: null, next: null };
  return { prev: flat[i - 1] || null, next: flat[i + 1] || null };
}
